1	#!/usr/bin/env node
2	// stockroom —— 本地多仓库存台账（Node.js 24，TypeScript，无外部运行依赖）
3	
4	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
5	import { join } from 'node:path';
6	
7	const APP_NAME = 'stockroom';
8	const DATA_FILENAME = 'stockroom.json';
9	const DEFAULT_DATA_DIR = '.stockroom';
10	
11	class UsageError extends Error {} // 命令行用法错误 -> 退出码 2
12	class BizError extends Error {} // 业务拒绝 -> 退出码 1
13	class DataError extends Error {} // 数据读取/保存失败 -> 退出码 1
14	
15	type DocType = 'in' | 'out' | 'transfer';
16	type EntryType = DocType | 'count' | 'in-rev' | 'out-rev' | 'transfer-rev' | 'count-rev';
17	
18	interface LedgerEntry {
19	  seq: number; // 全局流水序号，即提交顺序
20	  doc: string; // 单据编号（冲销流水此处为冲销单编号）
21	  type: EntryType;
22	  product: string;
23	  wh: string; // 本流水条目变动余量的仓库
24	  qty?: number; // 入库/出库/调拨类流水：恒为正数，方向由类型 / 出入仓决定；盘点类流水不用此字段
25	  before: number;
26	  after: number;
27	  from?: string; // 调拨（或冲销调拨）的调出仓
28	  to?: string; // 调拨（或冲销调拨）的调入仓
29	  orig?: string; // 冲销流水：被冲销的原单编号
30	  expected?: number; // 盘点（及冲销盘点）流水：预期账面量
31	  actual?: number; // 盘点（及冲销盘点）流水：实盘量
32	  diff?: number; // 盘点差额 = 实盘 - 账面（可正、可负、可零）；冲销盘点流水记录原差额
33	}
34	
35	interface DocRecord {
36	  content: Record<string, unknown>; // 规范化业务内容（明细顺序无关）
37	  resultLines: string[]; // 原提交结果，供幂等重放
38	}
39	
40	interface ReversalRecord {
41	  orig: string; // 被冲销的原单编号
42	  resultLines: string[]; // 冲销提交结果，供幂等重放
43	}
44	
45	interface Store {
46	  version: 1;
47	  products: Record<string, string>; // 编号 -> 名称（编号区分大小写；null 原型，防特殊键串改）
48	  stock: Record<string, Record<string, number>>; // 商品 -> 仓库 -> 余量
49	  entries: LedgerEntry[];
50	  docs: Record<string, DocRecord>; // 入库/出库/调拨单去重与结果
51	  reversals: Record<string, ReversalRecord>; // 冲销单去重与结果
52	}
53	
54	function nullProto<T extends object>(): T {
55	  return Object.create(null) as T;
56	}
57	
58	function emptyStore(): Store {
59	  return {
60	    version: 1,
61	    products: nullProto(),
62	    stock: nullProto(),
63	    entries: [],
64	    docs: nullProto(),
65	    reversals: nullProto(),
66	  };
67	}
68	
69	// ---------- 工具 ----------
70	
71	function isPlainObject(v: unknown): v is Record<string, unknown> {
72	  return typeof v === 'object' && v !== null && !Array.isArray(v);
73	}
74	
75	function isNonNegSafeInt(v: unknown): v is number {
76	  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
77	}
78	
79	function isPosSafeInt(v: unknown): v is number {
80	  return typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
81	}
82	
83	function trimOrThrow(label: string, raw: string): string {
84	  const s = raw.trim();
85	  if (s === '') throw new BizError(`${label}去除首尾空白后不能为空`);
86	  return s;
87	}
88	
89	/** 规范化序列化：对象键排序，保证业务内容比较与明细顺序无关。 */
90	function stableStringify(v: unknown): string {
91	  if (isPlainObject(v)) {
92	    return (
93	      '{' +
94	      Object.keys(v)
95	        .sort()
96	        .map((k) => JSON.stringify(k) + ':' + stableStringify(v[k]))
97	        .join(',') +
98	      '}'
99	    );
100	  }
101	  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
102	  return JSON.stringify(v);
103	}
104	
105	// ---------- 数据持久化 ----------
106	
107	function dataPath(dataDir: string): string {
108	  return join(dataDir, DATA_FILENAME);
109	}
110	
111	function loadStore(dataDir: string): Store {
112	  let raw: string;
113	  try {
114	    raw = readFileSync(dataPath(dataDir), 'utf8');
115	  } catch (e) {
116	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore(); // 尚不存在 -> 空库
117	    throw new DataError(`无法读取数据文件 ${dataPath(dataDir)}：${(e as Error).message}`);
118	  }
119	
120	  let data: unknown;
121	  try {
122	    // JSON.parse 将 "__proto__" 保留为普通自有属性（不设置原型）；随后 validateStore
123	    // 会把全部容器重新装入 null 原型对象，constructor 等特殊键同样安全。
124	    data = JSON.parse(raw);
125	  } catch {
126	    throw new DataError(`数据文件已损坏，无法解析 JSON：${dataPath(dataDir)}（不会作为空库覆盖）`);
127	  }
128	  return validateStore(data);
129	}
130	
131	function validateStore(data: unknown): Store {
132	  const bad = (msg: string): DataError =>
133	    new DataError(`数据文件已损坏或格式不正确（${msg}），拒绝启动以免覆盖原数据`);
134	
135	  if (!isPlainObject(data)) throw bad('根节点不是对象');
136	  if (data.version !== 1) throw bad(`不支持的数据版本：${String(data.version)}`);
137	
138	  // 重新装入 null 原型容器：即使磁盘数据来自普通对象，constructor/__proto__ 等键也安全
139	  const store = emptyStore();
140	
141	  if (!isPlainObject(data.products)) throw bad('products 不是对象');
142	  for (const [id, name] of Object.entries(data.products)) {
143	    if (typeof id !== 'string' || id.trim() === '' || typeof name !== 'string')
144	      throw bad('products 中存在非法编号或名称');
145	    store.products[id] = name;
146	  }
147	
148	  if (!isPlainObject(data.stock)) throw bad('stock 不是对象');
149	  for (const [pid, whs] of Object.entries(data.stock)) {
150	    if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的库存不是对象`);
151	    const whMap = nullProto<Record<string, number>>();
152	    for (const [wh, qty] of Object.entries(whs)) {
153	      if (typeof wh !== 'string' || wh.trim() === '' || !isNonNegSafeInt(qty))
154	        throw bad(`商品 ${pid} 仓库 ${String(wh)} 的余量非法`);
155	      whMap[wh] = qty;
156	    }
157	    store.stock[pid] = whMap;
158	  }
159	
160	  if (!Array.isArray(data.entries)) throw bad('entries 不是数组');
161	  let lastSeq = 0;
162	  for (const e of data.entries as unknown[]) {
163	    if (!isPlainObject(e)) throw bad('存在非法流水条目');
164	    if (!isPosSafeInt(e.seq) || e.seq !== ++lastSeq) throw bad('流水序号不连续');
165	    if (typeof e.doc !== 'string' || e.doc.trim() === '') throw bad('流水缺少单据编号');
166	    const isRev =
167	      e.type === 'in-rev' || e.type === 'out-rev' || e.type === 'transfer-rev' || e.type === 'count-rev';
168	    const isOrig = e.type === 'in' || e.type === 'out' || e.type === 'transfer' || e.type === 'count';
169	    if (!isRev && !isOrig) throw bad('流水类型非法');
170	    if (typeof e.product !== 'string' || e.product.trim() === '') throw bad('流水缺少商品编号');
171	    if (typeof e.wh !== 'string' || e.wh.trim() === '') throw bad('流水缺少仓库标识');
172	    if (!isNonNegSafeInt(e.before) || !isNonNegSafeInt(e.after)) throw bad('流水余量非法');
173	    if (e.type === 'count' || e.type === 'count-rev') {
174	      if (!isNonNegSafeInt(e.expected) || !isNonNegSafeInt(e.actual))
175	        throw bad('盘点流水账面/实盘量非法');
176	      if (typeof e.diff !== 'number' || !Number.isSafeInteger(e.diff)) throw bad('盘点流水差额非法');
177	      if (e.diff !== e.actual - e.expected) throw bad('盘点流水差额与账面、实盘量不一致');
178	      const applied = e.type === 'count' ? e.diff : -e.diff; // 冲销盘点应用反向差额
179	      if (e.after - e.before !== applied) throw bad('盘点流水差额与前后余量不一致');
180	      if (e.qty !== undefined || e.from !== undefined || e.to !== undefined)
181	        throw bad('盘点流水不应携带数量或调拨字段');
182	    } else {
183	      if (!isPosSafeInt(e.qty)) throw bad('流水数量非法');
184	      if (e.expected !== undefined || e.actual !== undefined || e.diff !== undefined)
185	        throw bad('非盘点流水不应携带盘点字段');
186	      const delta = e.after - e.before;
187	      if (e.type === 'transfer' || e.type === 'transfer-rev') {
188	        if (typeof e.from !== 'string' || e.from.trim() === '' || typeof e.to !== 'string' || e.to.trim() === '')
189	          throw bad('调拨流水缺少调出/调入仓');
190	        // 调拨：调入仓增加；冲销调拨：原调入仓扣回、原调出仓补回
191	        const expect = (e.wh === e.to) === (e.type === 'transfer') ? e.qty : -e.qty;
192	        if (delta !== expect) throw bad('流水差额与前后余量不一致');
193	      } else {
194	        const increases = e.type === 'in' || e.type === 'out-rev';
195	        if (delta !== (increases ? e.qty : -e.qty)) throw bad('流水差额与前后余量不一致');
196	      }
197	    }
198	    if (isRev) {
199	      if (typeof e.orig !== 'string' || e.orig.trim() === '') throw bad('冲销流水缺少原单编号');
200	    } else if (e.orig !== undefined) {
201	      throw bad('原始单据流水不应携带冲销标记');
202	    }
203	    store.entries.push(e as unknown as LedgerEntry);
204	  }
205	
206	  if (!isPlainObject(data.docs)) throw bad('docs 不是对象');
207	  for (const [docId, rec] of Object.entries(data.docs)) {
208	    if (typeof docId !== 'string' || docId.trim() === '') throw bad('存在非法单据编号');
209	    if (!isPlainObject(rec) || !isPlainObject(rec.content) || !Array.isArray(rec.resultLines))
210	      throw bad(`单据 ${docId} 的去重记录非法`);
211	    if (!rec.resultLines.every((l) => typeof l === 'string')) throw bad(`单据 ${docId} 的结果记录非法`);
212	    const c = rec.content;
213	    if (c.type !== 'in' && c.type !== 'out' && c.type !== 'transfer' && c.type !== 'count')
214	      throw bad(`单据 ${docId} 的业务类型非法`);
215	    if (!isPlainObject(c.items)) throw bad(`单据 ${docId} 的明细非法`);
216	    for (const [pid, item] of Object.entries(c.items)) {
217	      if (pid.trim() === '') throw bad(`单据 ${docId} 存在非法明细`);
218	      if (c.type === 'count') {
219	        if (!isPlainObject(item) || !isNonNegSafeInt(item.expected) || !isNonNegSafeInt(item.actual))
220	          throw bad(`单据 ${docId} 存在非法盘点明细`);
221	      } else if (!isPosSafeInt(item)) {
222	        throw bad(`单据 ${docId} 存在非法明细`);
223	      }
224	    }
225	    if (c.type === 'transfer') {
226	      if (typeof c.from !== 'string' || c.from.trim() === '' || typeof c.to !== 'string' || c.to.trim() === '')
227	        throw bad(`单据 ${docId} 的调拨仓非法`);
228	    } else if (typeof c.wh !== 'string' || c.wh.trim() === '') {
229	      throw bad(`单据 ${docId} 的仓库非法`);
230	    }
231	    store.docs[docId] = rec as unknown as DocRecord;
232	  }
233	
234	  // reversals 为新增字段：合法旧数据没有该字段，按空集合处理
235	  if (data.reversals !== undefined) {
236	    if (!isPlainObject(data.reversals)) throw bad('reversals 不是对象');
237	    for (const [revId, rec] of Object.entries(data.reversals)) {
238	      if (typeof revId !== 'string' || revId.trim() === '') throw bad('存在非法冲销单编号');
239	      if (!isPlainObject(rec) || typeof rec.orig !== 'string' || rec.orig.trim() === '' ||
240	          !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string'))
241	        throw bad(`冲销单 ${revId} 的记录非法`);
242	      const origRec = store.docs[rec.orig];
243	      if (origRec === undefined) throw bad(`冲销单 ${revId} 指向的原单 ${rec.orig} 不存在`);
244	      if (store.docs[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与原始单据编号冲突`);
245	      store.reversals[revId] = { orig: rec.orig, resultLines: rec.resultLines };
246	    }
247	    // 每张原单最多被成功冲销一次
248	    const origSeen = nullProto<Record<string, string>>();
249	    for (const [revId, rec] of Object.entries(store.reversals)) {
250	      if (origSeen[rec.orig] !== undefined)
251	        throw bad(`原单 ${rec.orig} 被多张冲销单关联（${origSeen[rec.orig]}、${revId}）`);
252	      origSeen[rec.orig] = revId;
253	    }
254	    // 冲销流水必须能找到所属冲销单
255	    for (const e of store.entries) {
256	      if ((e.type === 'in-rev' || e.type === 'out-rev' || e.type === 'transfer-rev' || e.type === 'count-rev') &&
257	          store.reversals[e.doc] === undefined)
258	        throw bad(`流水引用了不存在的冲销单 ${e.doc}`);
259	    }
260	  }
261	
262	  return store;
263	}
264	
265	function saveStore(dataDir: string, store: Store): void {
266	  const path = dataPath(dataDir);
267	  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.tmp`);
268	  try {
269	    mkdirSync(dataDir, { recursive: true });
270	    writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n', 'utf8');
271	    renameSync(tmp, path);
272	  } catch (e) {
273	    throw new DataError(`保存数据失败，已有数据保持不变：${(e as Error).message}`);
274	  }
275	}
276	
277	// ---------- 参数解析 ----------
278	
279	interface ParsedArgs {
280	  positionals: string[];
281	  flags: Record<string, string>;
282	  multi: Record<string, string[]>;
283	}
284	
285	function parseArgs(
286	  tokens: string[],
287	  singles: string[],
288	  multis: string[] = [],
289	): ParsedArgs {
290	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
291	  const singleSet = new Set(singles);
292	  const multiSet = new Set(multis);
293	
294	  for (let i = 0; i < tokens.length; i++) {
295	    const tok = tokens[i];
296	    if (tok.startsWith('--')) {
297	      let key = tok;
298	      let value: string | undefined;
299	      const eq = tok.indexOf('=');
300	      if (eq >= 0) {
301	        key = tok.slice(0, eq);
302	        value = tok.slice(eq + 1);
303	      }
304	      if (!singleSet.has(key) && !multiSet.has(key)) throw new UsageError(`未知参数：${tok}`);
305	      if (value === undefined) {
306	        if (i + 1 >= tokens.length) throw new UsageError(`参数 ${key} 缺少取值`);
307	        value = tokens[++i];
308	      }
309	      if (multiSet.has(key)) (out.multi[key] ??= []).push(value);
310	      else if (out.flags[key] !== undefined) throw new UsageError(`参数 ${key} 重复指定`);
311	      else out.flags[key] = value;
312	    } else {
313	      out.positionals.push(tok);
314	    }
315	  }
316	  return out;
317	}
318	
319	function parseItem(raw: string, merged: Map<string, number>): void {
320	  const idx = raw.indexOf(':');
321	  if (idx <= 0) throw new BizError(`明细格式应为 “商品编号:数量”：${raw}`);
322	  const pid = trimOrThrow('商品编号', raw.slice(0, idx));
323	  const qtyRaw = raw.slice(idx + 1).trim();
324	  if (!/^\d+$/.test(qtyRaw)) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
325	  const qty = Number(qtyRaw);
326	  if (!Number.isSafeInteger(qty) || qty <= 0) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
327	  const sum = (merged.get(pid) ?? 0) + qty; // 同单同商品先合并
328	  if (!Number.isSafeInteger(sum)) throw new BizError(`商品 ${pid} 累计数量超出安全整数范围`);
329	  merged.set(pid, sum);
330	}
331	
332	interface DocRequest {
333	  type: DocType;
334	  docId: string;
335	  wh?: string;
336	  from?: string;
337	  to?: string;
338	  items: Map<string, number>;
339	}
340	
341	function parseDocArgs(type: DocType, tokens: string[]): DocRequest {
342	  const args = parseArgs(tokens, type === 'transfer' ? ['--from', '--to'] : ['--wh'], ['--item']);
343	  const docId = args.positionals[0];
344	  if (docId === undefined || args.positionals.length !== 1)
345	    throw new UsageError(`用法：单据命令需要且仅需要一个单据编号`);
346	
347	  const items = new Map<string, number>();
348	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
349	  if (items.size === 0) throw new UsageError('单据至少需要一条 --item 商品编号:数量 明细');
350	
351	  const req: DocRequest = { type, docId: trimOrThrow('单据编号', docId), items };
352	  if (type === 'transfer') {
353	    if (args.flags['--from'] === undefined || args.flags['--to'] === undefined)
354	      throw new UsageError('调拨单必须提供 --from <调出仓> 与 --to <调入仓>');
355	    req.from = trimOrThrow('调出仓标识', args.flags['--from']);
356	    req.to = trimOrThrow('调入仓标识', args.flags['--to']);
357	    if (req.from === req.to) throw new BizError('调拨单的调出仓与调入仓不能相同');
358	  } else {
359	    if (args.flags['--wh'] === undefined) throw new UsageError('入库/出库单必须提供 --wh <仓库>');
360	    req.wh = trimOrThrow('仓库标识', args.flags['--wh']);
361	  }
362	  return req;
363	}
364	
365	interface CountItem {
366	  expected: number; // 预期账面量
367	  actual: number; // 实盘量
368	}
369	
370	interface CountRequest {
371	  docId: string;
372	  wh: string;
373	  items: Map<string, CountItem>;
374	}
375	
376	function parseNonNegInt(label: string, raw: string): number {
377	  const s = raw.trim();
378	  if (!/^\d+$/.test(s)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
379	  const n = Number(s);
380	  if (!Number.isSafeInteger(n)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
381	  return n;
382	}
383	
384	function parseCountArgs(tokens: string[]): CountRequest {
385	  const args = parseArgs(tokens, ['--wh'], ['--item']);
386	  const docId = args.positionals[0];
387	  if (docId === undefined || args.positionals.length !== 1)
388	    throw new UsageError('用法：count <单据编号> --wh <仓库> --item <商品编号:预期账面量:实盘量> [...]');
389	  if (args.flags['--wh'] === undefined) throw new UsageError('盘点单必须提供 --wh <仓库>');
390	
391	  const items = new Map<string, CountItem>();
392	  for (const raw of args.multi['--item'] ?? []) {
393	    const parts = raw.split(':');
394	    if (parts.length !== 3)
395	      throw new BizError(`盘点明细格式应为 “商品编号:预期账面量:实盘量”：${raw}`);
396	    const pid = trimOrThrow('商品编号', parts[0]);
397	    const expected = parseNonNegInt(`商品 ${pid} 的预期账面量`, parts[1]);
398	    const actual = parseNonNegInt(`商品 ${pid} 的实盘量`, parts[2]);
399	    if (items.has(pid)) throw new BizError(`盘点单中商品 ${pid} 重复出现，拒绝提交`);
400	    items.set(pid, { expected, actual });
401	  }
402	  if (items.size === 0)
403	    throw new UsageError('盘点单至少需要一条 --item 商品编号:预期账面量:实盘量 明细');
404	
405	  return { docId: trimOrThrow('单据编号', docId), wh: trimOrThrow('仓库标识', args.flags['--wh']), items };
406	}
407	
408	// ---------- 整批导入文件解析 ----------
409	
410	type ImportRequest =
411	  | { kind: 'doc'; req: DocRequest }
412	  | { kind: 'count'; req: CountRequest }
413	  | { kind: 'reverse'; docId: string; orig: string };
414	
415	/** 读取导入文件：无法读取属于读写失败（退出 1），不改变任何已提交状态。 */
416	function readImportFile(file: string): string {
417	  try {
418	    return readFileSync(file, 'utf8');
419	  } catch (e) {
420	    throw new DataError(`无法读取导入文件 ${file}：${(e as Error).message}（不会改变任何已提交数据）`);
421	  }
422	}
423	
424	/**
425	 * 解析整批导入文件。文件级结构错误（非合法 JSON、根不是数组、空列表）属于文件
426	 * 格式错误（退出 2）；逐项格式不合法属于业务拒绝（退出 1），指出位置与原因。
427	 */
428	function parseImportFile(raw: string): ImportRequest[] {
429	  let data: unknown;
430	  try {
431	    data = JSON.parse(raw);
432	  } catch (e) {
433	    throw new UsageError(`导入文件不是合法 JSON：${(e as Error).message}`);
434	  }
435	  if (!Array.isArray(data)) throw new UsageError('导入文件格式错误：根节点必须是单据对象组成的有序数组');
436	  if (data.length === 0) throw new UsageError('导入文件格式错误：单据列表至少包含一项');
437	
438	  const out: ImportRequest[] = [];
439	  // 顶层位置一律标注 1 起序号，便于纠正
440	  const at = (i: number, msg: string): BizError => new BizError(`第 ${i + 1} 项：${msg}`);
441	
442	  const requireString = (obj: Record<string, unknown>, key: string, label: string, i: number): string => {
443	    const v = obj[key];
444	    if (v === undefined) throw at(i, `缺少${label}字段 "${key}"`);
445	    if (typeof v !== 'string') throw at(i, `${label}字段 "${key}" 必须是字符串`);
446	    const s = v.trim();
447	    if (s === '') throw at(i, `${label}去除首尾空白后不能为空`);
448	    return s;
449	  };
450	
451	  const checkUnknown = (obj: Record<string, unknown>, allowed: readonly string[], i: number): void => {
452	    for (const k of Object.keys(obj)) {
453	      if (!allowed.includes(k)) throw at(i, `含不支持的字段 "${k}"（允许字段：${allowed.join('、')}）`);
454	    }
455	  };
456	
457	  const parseQtyItems = (obj: Record<string, unknown>, i: number): Map<string, number> => {
458	    const v = obj.items;
459	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
460	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
461	    if (v.length === 0) throw at(i, '商品明细至少一项');
462	    const merged = new Map<string, number>();
463	    v.forEach((entry, j) => {
464	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
465	      const e = entry as Record<string, unknown>;
466	      checkUnknown(e, ['product', 'qty'], i);
467	      const pid = e.product;
468	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
469	      const p = pid.trim();
470	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
471	      if (!isPosSafeInt(e.qty)) throw at(i, `商品 ${p} 的数量必须为正安全整数`);
472	      const sum = (merged.get(p) ?? 0) + (e.qty as number); // 同单同商品先合并
473	      if (!Number.isSafeInteger(sum)) throw at(i, `商品 ${p} 累计数量超出安全整数范围`);
474	      merged.set(p, sum);
475	    });
476	    return merged;
477	  };
478	
479	  const parseCountItems = (obj: Record<string, unknown>, i: number): Map<string, CountItem> => {
480	    const v = obj.items;
481	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
482	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
483	    if (v.length === 0) throw at(i, '商品明细至少一项');
484	    const items = new Map<string, CountItem>();
485	    v.forEach((entry, j) => {
486	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
487	      const e = entry as Record<string, unknown>;
488	      checkUnknown(e, ['product', 'expected', 'actual'], i);
489	      const pid = e.product;
490	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
491	      const p = pid.trim();
492	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
493	      if (!isNonNegSafeInt(e.expected)) throw at(i, `商品 ${p} 的预期账面量必须为非负安全整数`);
494	      if (!isNonNegSafeInt(e.actual)) throw at(i, `商品 ${p} 的实盘量必须为非负安全整数`);
495	      if (items.has(p)) throw at(i, `盘点明细中商品 ${p} 重复出现，拒绝提交`); // 盘点不合并
496	      items.set(p, { expected: e.expected, actual: e.actual });
497	    });
498	    return items;
499	  };
500	
501	  data.forEach((rawItem, i) => {
502	    if (!isPlainObject(rawItem)) throw at(i, '不是单据对象');
503	    const item = rawItem as Record<string, unknown>;
504	    if (item.type === undefined) throw at(i, '缺少业务类型字段 "type"');
505	    if (typeof item.type !== 'string') throw at(i, '业务类型字段 "type" 必须是字符串');
506	
507	    switch (item.type) {
508	      case 'in':
509	      case 'out': {
510	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
511	        const docId = requireString(item, 'id', '单据编号', i);
512	        const wh = requireString(item, 'wh', '仓库标识', i);
513	        out.push({ kind: 'doc', req: { type: item.type, docId, wh, items: parseQtyItems(item, i) } });
514	        break;
515	      }
516	      case 'transfer': {
517	        checkUnknown(item, ['type', 'id', 'from', 'to', 'items'], i);
518	        const docId = requireString(item, 'id', '单据编号', i);
519	        const from = requireString(item, 'from', '调出仓标识', i);
520	        const to = requireString(item, 'to', '调入仓标识', i);
521	        if (from === to) throw at(i, '调拨单的调出仓与调入仓不能相同');
522	        out.push({ kind: 'doc', req: { type: 'transfer', docId, from, to, items: parseQtyItems(item, i) } });
523	        break;
524	      }
525	      case 'count': {
526	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
527	        const docId = requireString(item, 'id', '单据编号', i);
528	        const wh = requireString(item, 'wh', '仓库标识', i);
529	        out.push({ kind: 'count', req: { docId, wh, items: parseCountItems(item, i) } });
530	        break;
531	      }
532	      case 'reverse': {
533	        checkUnknown(item, ['type', 'id', 'orig'], i);
534	        const docId = requireString(item, 'id', '冲销单编号', i);
535	        const orig = requireString(item, 'orig', '原单编号', i);
536	        out.push({ kind: 'reverse', docId, orig });
537	        break;
538	      }
539	      default:
540	        throw at(i, `不支持的业务类型 "${String(item.type)}"，只允许 in、out、transfer、count、reverse`);
541	    }
542	  });
543	
544	  return out;
545	}
546	
547	// ---------- 业务核心 ----------
548	
549	const MAX_SAFE = Number.MAX_SAFE_INTEGER;
550	
551	/** 带符号数量文本：正数加 +，负数保留 -，零为 0。 */
552	function fmtSigned(n: number): string {
553	  return n > 0 ? `+${n}` : String(n);
554	}
555	
556	function canonicalContent(req: DocRequest): Record<string, unknown> {
557	  const items: Record<string, number> = nullProto();
558	  for (const pid of [...req.items.keys()].sort()) items[pid] = req.items.get(pid)!;
559	  if (req.type === 'transfer') return { type: req.type, from: req.from!, to: req.to!, items };
560	  return { type: req.type, wh: req.wh!, items };
561	}
562	
563	function getStock(stock: Store['stock'], pid: string, wh: string): number {
564	  return stock[pid]?.[wh] ?? 0;
565	}
566	
567	function setStock(stock: Store['stock'], pid: string, wh: string, qty: number): void {
568	  (stock[pid] ??= nullProto<Record<string, number>>())[wh] = qty;
569	}
570	
571	/**
572	 * 深拷贝余量草稿。必须自建 null 原型容器：structuredClone 不保留 null 原型，
573	 * 普通对象在 "__proto__"/"constructor" 等商品或仓库键下会发生原型串改。
574	 */
575	function cloneStock(stock: Store['stock']): Store['stock'] {
576	  const out = nullProto<Store['stock']>();
577	  for (const pid of Object.keys(stock)) {
578	    const whMap = nullProto<Record<string, number>>();
579	    for (const wh of Object.keys(stock[pid])) whMap[wh] = stock[pid][wh];
580	    out[pid] = whMap;
581	  }
582	  return out;
583	}
584	
585	function canonicalCountContent(req: CountRequest): Record<string, unknown> {
586	  const items: Record<string, unknown> = nullProto();
587	  for (const pid of [...req.items.keys()].sort()) {
588	    const it = req.items.get(pid)!;
589	    items[pid] = { expected: it.expected, actual: it.actual };
590	  }
591	  return { type: 'count', wh: req.wh, items };
592	}
593	
594	interface ApplyOutcome {
595	  duplicate: boolean;
596	  header: string; // 结果首行汇总
597	  lines: string[]; // 逐项明细结果
598	  repeatedFrom?: 'store' | 'batch'; // 重复项来自导入前已存数据，还是本批此前各项
599	}
600	
601	/**
602	 * 账务模拟器：单条命令与整批导入共用。所有变动先落在草稿余量与新增流水上，
603	 * 编号去重视图（docs/revs）在模拟期间即时更新但不写回 base，全部项通过后由
604	 * commit 一次性落库；模拟途中抛错则 base 与磁盘均不受影响。
605	 */
606	class Ledger {
607	  private readonly base: Store;
608	  private readonly draft: Store['stock'];
609	  private readonly additions: LedgerEntry[] = [];
610	  private seq: number;
611	  private readonly docs: Record<string, DocRecord> = nullProto();
612	  private readonly revs: Record<string, ReversalRecord> = nullProto();
613	  private readonly reversedOrigs = new Set<string>();
614	  private readonly newDocIds: string[] = [];
615	  private readonly newRevIds: string[] = [];
616	
617	  constructor(store: Store) {
618	    this.base = store;
619	    this.draft = cloneStock(store.stock);
620	    this.seq = store.entries.length;
621	    for (const [id, rec] of Object.entries(store.docs)) this.docs[id] = rec;
622	    for (const [id, rec] of Object.entries(store.reversals)) {
623	      this.revs[id] = rec;
624	      this.reversedOrigs.add(rec.orig);
625	    }
626	  }
627	
628	  /** 是否有新生效单据：无新单据（全部重复）时 commit 不改写数据。 */
629	  get changed(): boolean {
630	    return this.newDocIds.length + this.newRevIds.length > 0;
631	  }
632	
633	  /** 重建原始单据结果首行，供幂等重放。 */
634	  private docHeader(docId: string, rec: DocRecord): string {
635	    const c = rec.content;
636	    const n = Object.keys(c.items as Record<string, unknown>).length;
637	    return c.type === 'count'
638	      ? `盘点单 ${docId} 提交成功，仓库 ${c.wh as string}，共 ${n} 种商品：`
639	      : `${c.type === 'in' ? '入库' : c.type === 'out' ? '出库' : '调拨'}单 ${docId} 提交成功，共 ${n} 种商品：`;
640	  }
641	
642	  /** 重建冲销单结果首行，供幂等重放。 */
643	  private revHeader(revId: string, rec: ReversalRecord): string {
644	    const origRec = this.docs[rec.orig]; // 能进入去重视图的冲销单必然指向存在的原单
645	    const type = origRec.content.type as string;
646	    const label = type === 'in' ? '入库' : type === 'out' ? '出库' : type === 'transfer' ? '调拨' : '盘点';
647	    const n = Object.keys(origRec.content.items as Record<string, unknown>).length;
648	    return `冲销单 ${revId} 提交成功，冲销${label}原单 ${rec.orig}，共 ${n} 种商品：`;
649	  }
650	
651	  private repeatedRevSource(revId: string): 'store' | 'batch' {
652	    return this.base.reversals[revId] !== undefined ? 'store' : 'batch';
653	  }
654	
655	  private repeatedDocSource(docId: string): 'store' | 'batch' {
656	    return this.base.docs[docId] !== undefined ? 'store' : 'batch';
657	  }
658	
659	  /** 整单先校验、模拟，全部合法后才登记到草稿；任一明细失败则整批保持原状。 */
660	  applyDoc(req: DocRequest): ApplyOutcome {
661	    const content = canonicalContent(req);
662	    const existed = this.docs[req.docId];
663	    if (existed !== undefined) {
664	      if (stableStringify(existed.content) !== stableStringify(content))
665	        throw new BizError(`单据编号 ${req.docId} 已用于业务内容不同的单据，拒绝提交`);
666	      return { duplicate: true, header: this.docHeader(req.docId, existed), lines: existed.resultLines, repeatedFrom: this.repeatedDocSource(req.docId) };
667	    }
668	    // 编号空间与出库/入库/调拨/冲销单共用
669	    if (this.revs[req.docId] !== undefined)
670	      throw new BizError(`单据编号 ${req.docId} 已用于冲销单，拒绝提交`);
671	
672	    for (const pid of req.items.keys()) {
673	      if (this.base.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
674	    }
675	
676	    const reportLines: string[] = [];
677	    const typeLabel = req.type === 'in' ? '入库' : req.type === 'out' ? '出库' : '调拨';
678	
679	    for (const pid of [...req.items.keys()].sort()) {
680	      const qty = req.items.get(pid)!;
681	
682	      if (req.type === 'in') {
683	        const wh = req.wh!;
684	        const before = getStock(this.draft, pid, wh);
685	        const after = before + qty;
686	        if (after > MAX_SAFE) throw new BizError(`商品 ${pid} 入库后余量超出安全整数范围，拒绝整单`);
687	        setStock(this.draft, pid, wh, after);
688	        this.additions.push({ seq: ++this.seq, doc: req.docId, type: 'in', product: pid, wh, qty, before, after });
689	        reportLines.push(`入库 ${pid} @${wh} +${qty}：${before} -> ${after}`);
690	      } else if (req.type === 'out') {
691	        const wh = req.wh!;
692	        const before = getStock(this.draft, pid, wh);
693	        if (before < qty)
694	          throw new BizError(`商品 ${pid} 仓库 ${wh} 余量不足（当前 ${before}，需出库 ${qty}），拒绝整单`);
695	        const after = before - qty;
696	        setStock(this.draft, pid, wh, after);
697	        this.additions.push({ seq: ++this.seq, doc: req.docId, type: 'out', product: pid, wh, qty, before, after });
698	        reportLines.push(`出库 ${pid} @${wh} -${qty}：${before} -> ${after}`);
699	      } else {
700	        const from = req.from!;
701	        const to = req.to!;
702	        const beforeFrom = getStock(this.draft, pid, from);
703	        if (beforeFrom < qty)
704	          throw new BizError(`商品 ${pid} 调出仓 ${from} 余量不足（当前 ${beforeFrom}，需调拨 ${qty}），拒绝整单`);
705	        const afterFrom = beforeFrom - qty;
706	        const beforeTo = getStock(this.draft, pid, to);
707	        const afterTo = beforeTo + qty;
708	        if (afterTo > MAX_SAFE) throw new BizError(`商品 ${pid} 调入后余量超出安全整数范围，拒绝整单`);
709	        setStock(this.draft, pid, from, afterFrom);
710	        setStock(this.draft, pid, to, afterTo);
711	        this.additions.push({
712	          seq: ++this.seq, doc: req.docId, type: 'transfer', product: pid, wh: from,
713	          qty, before: beforeFrom, after: afterFrom, from, to,
714	        });
715	        this.additions.push({
716	          seq: ++this.seq, doc: req.docId, type: 'transfer', product: pid, wh: to,
717	          qty, before: beforeTo, after: afterTo, from, to,
718	        });
719	        reportLines.push(
720	          `调拨 ${pid} ${from} -> ${to} ${qty}：${from} ${beforeFrom}->${afterFrom}；${to} ${beforeTo}->${afterTo}`,
721	        );
722	      }
723	    }
724	
725	    // 全部明细合法：登记到模拟视图；真正落库由 commit 统一完成
726	    this.docs[req.docId] = { content, resultLines: reportLines };
727	    this.newDocIds.push(req.docId);
728	
729	    const header = `${typeLabel}单 ${req.docId} 提交成功，共 ${req.items.size} 种商品：`;
730	    return { duplicate: false, header, lines: reportLines };
731	  }
732	
733	  /**
734	   * 整单盘点校正：首次提交先逐项核对当前（草稿）余量与预期账面量，任一不符整单拒绝
735	   * 并说明冲突商品及当前量；全部相符才把列出的商品校正为实盘量（差额 = 实盘 - 账面，
736	   * 可增、可减、可为零），未列出的商品及其他仓库不变。同编号同内容重放只返回原
737	   * 结果，即使余量改变或盘点已冲销也不再核对、不再生效。
738	   */
739	  applyCount(req: CountRequest): ApplyOutcome {
740	    const content = canonicalCountContent(req);
741	    const existed = this.docs[req.docId];
742	    if (existed !== undefined) {
743	      if (stableStringify(existed.content) !== stableStringify(content))
744	        throw new BizError(`单据编号 ${req.docId} 已用于业务内容不同的单据，拒绝提交`);
745	      return { duplicate: true, header: this.docHeader(req.docId, existed), lines: existed.resultLines, repeatedFrom: this.repeatedDocSource(req.docId) };
746	    }
747	    // 编号空间与入库/出库/调拨/冲销单共用
748	    if (this.revs[req.docId] !== undefined)
749	      throw new BizError(`单据编号 ${req.docId} 已用于冲销单，拒绝提交`);
750	
751	    const pids = [...req.items.keys()].sort();
752	    for (const pid of pids) {
753	      if (this.base.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
754	    }
755	
756	    // 账面核对：任一商品的当前余量与预期账面量不符，整单拒绝并说明冲突商品及当前量
757	    const conflicts: string[] = [];
758	    for (const pid of pids) {
759	      const current = getStock(this.draft, pid, req.wh);
760	      const expected = req.items.get(pid)!.expected;
761	      if (current !== expected)
762	        conflicts.push(`商品 ${pid}：当前余量 ${current}，预期账面量 ${expected}`);
763	    }
764	    if (conflicts.length > 0)
765	      throw new BizError(`盘点单 ${req.docId} 账面核对不符，拒绝整单：\n${conflicts.join('\n')}`);
766	
767	    const reportLines: string[] = [];
768	
769	    for (const pid of pids) {
770	      const { expected, actual } = req.items.get(pid)!;
771	      const before = getStock(this.draft, pid, req.wh); // 核对通过，与预期账面量一致
772	      const after = actual;
773	      const diff = actual - expected; // 差额 = 实盘 - 账面，可增、可减、可为零
774	      setStock(this.draft, pid, req.wh, after);
775	      this.additions.push({
776	        seq: ++this.seq, doc: req.docId, type: 'count', product: pid, wh: req.wh,
777	        expected, actual, diff, before, after,
778	      });
779	      reportLines.push(
780	        `盘点 ${pid} @${req.wh} 账面=${expected} 实盘=${actual} 差额=${fmtSigned(diff)}：${before} -> ${after}`,
781	      );
782	    }
783	
784	    this.docs[req.docId] = { content, resultLines: reportLines };
785	    this.newDocIds.push(req.docId);
786	
787	    const header = `盘点单 ${req.docId} 提交成功，仓库 ${req.wh}，共 ${pids.length} 种商品：`;
788	    return { duplicate: false, header, lines: reportLines };
789	  }
790	
791	  /**
792	   * 整单冲销：在“当前余量”上应用原单的相反变动（不回滚历史、不恢复绝对余量）。
793	   * 原单可以是导入前已成功的单据，也可以是本批此前已模拟生效的新原单；
794	   * 冲销单不可冲销，每张原单最多冲销一次。
795	   */
796	  applyReversal(revId: string, origId: string): ApplyOutcome {
797	    const existed = this.revs[revId];
798	    if (existed !== undefined) {
799	      if (existed.orig !== origId)
800	        throw new BizError(
801	          `冲销单编号 ${revId} 已用于冲销原单 ${existed.orig}，不能改冲原单 ${origId}，拒绝提交`,
802	        );
803	      return { duplicate: true, header: this.revHeader(revId, existed), lines: existed.resultLines, repeatedFrom: this.repeatedRevSource(revId) };
804	    }
805	    // 冲销单与入库/出库/调拨/盘点共用唯一编号空间
806	    if (this.docs[revId] !== undefined)
807	      throw new BizError(`编号 ${revId} 已是入库/出库/调拨/盘点单编号，不能用作冲销单，拒绝提交`);
808	
809	    // 只能冲销成功的原始库存单据：不存在（含列表中尚未出现）的原单、冲销单本身均不可冲销
810	    const origRec = this.docs[origId];
811	    if (origRec === undefined) {
812	      if (this.revs[origId] !== undefined)
813	        throw new BizError(`原单 ${origId} 是冲销单，冲销单不可冲销，拒绝提交`);
