816	
817	    if (this.reversedOrigs.has(origId)) {
818	      let existingRev = '';
819	      for (const [r, rec] of Object.entries(this.revs)) {
820	        if (rec.orig === origId) {
821	          existingRev = r;
822	          break;
823	        }
824	      }
825	      throw new BizError(`原单 ${origId} 已被冲销单 ${existingRev} 成功冲销，每张原单只能冲销一次`);
826	    }
827	
828	    const c = origRec.content;
829	    const type = c.type as DocType | 'count';
830	    const items = c.items as Record<string, number>;
831	    const pids = Object.keys(items).sort();
832	    const typeLabel = type === 'in' ? '入库' : type === 'out' ? '出库' : type === 'transfer' ? '调拨' : '盘点';
833	    const revType = `${type}-rev` as EntryType;
834	    const reportLines: string[] = [];
835	
836	    for (const pid of pids) {
837	      if (type === 'count') {
838	        // 冲销盘点：在当前余量上减去原盘点差额（不恢复原账面绝对值）；零差额不改余量但须记录
839	        const wh = c.wh as string;
840	        const item = (c.items as Record<string, { expected: number; actual: number }>)[pid];
841	        const diff = item.actual - item.expected;
842	        const before = getStock(this.draft, pid, wh);
843	        const after = before - diff;
844	        if (after < 0)
845	          throw new BizError(
846	            `冲销盘点原单 ${origId}：商品 ${pid} 仓库 ${wh} 当前余量 ${before} 冲减差额 ${fmtSigned(diff)} 后为负，拒绝整单`,
847	          );
848	        if (after > MAX_SAFE)
849	          throw new BizError(
850	            `冲销盘点原单 ${origId}：商品 ${pid} 仓库 ${wh} 冲减差额 ${fmtSigned(diff)} 后超出安全整数范围，拒绝整单`,
851	          );
