853	        this.additions.push({
854	          seq: ++this.seq, doc: revId, type: revType, product: pid, wh,
855	          expected: item.expected, actual: item.actual, diff, before, after, orig: origId,
856	        });
857	        reportLines.push(
858	          `冲销盘点 原单=${origId} 商品=${pid} @${wh} 反向差额=${fmtSigned(-diff)}：${before} -> ${after}`,
859	        );
860	        continue;
861	      }
862	      const qty = items[pid]; // 原单同商品合并后的数量
863	
864	      if (type === 'in') {
865	        // 冲销入库：从原目标仓扣回
866	        const wh = c.wh as string;
867	        const before = getStock(this.draft, pid, wh);
868	        if (before < qty)
869	          throw new BizError(
870	            `冲销入库原单 ${origId}：商品 ${pid} 仓库 ${wh} 当前余量 ${before} 不足扣回 ${qty}，拒绝整单`,
871	          );
872	        const after = before - qty;
873	        setStock(this.draft, pid, wh, after);
874	        this.additions.push({
875	          seq: ++this.seq, doc: revId, type: revType, product: pid, wh, qty, before, after, orig: origId,
876	        });
877	        reportLines.push(`冲销入库 原单=${origId} 商品=${pid} @${wh} -${qty}：${before} -> ${after}`);
878	      } else if (type === 'out') {
879	        // 冲销出库：向原来源仓补回
880	        const wh = c.wh as string;
881	        const before = getStock(this.draft, pid, wh);
882	        const after = before + qty;
883	        if (after > MAX_SAFE)
884	          throw new BizError(
885	            `冲销出库原单 ${origId}：商品 ${pid} 仓库 ${wh} 补回后余量超出安全整数范围，拒绝整单`,
886	          );
887	        setStock(this.draft, pid, wh, after);
888	        this.additions.push({
889	          seq: ++this.seq, doc: revId, type: revType, product: pid, wh, qty, before, after, orig: origId,
890	        });
891	        reportLines.push(`冲销出库 原单=${origId} 商品=${pid} @${wh} +${qty}：${before} -> ${after}`);
892	      } else {
893	        // 冲销调拨：从原调入仓扣回，向原调出仓补回
894	        const from = c.from as string;
895	        const to = c.to as string;
896	        const beforeTo = getStock(this.draft, pid, to);
897	        if (beforeTo < qty)
898	          throw new BizError(
899	            `冲销调拨原单 ${origId}：商品 ${pid} 原调入仓 ${to} 当前余量 ${beforeTo} 不足扣回 ${qty}，拒绝整单`,
900	          );
901	        const afterTo = beforeTo - qty;
902	        const beforeFrom = getStock(this.draft, pid, from);
903	        const afterFrom = beforeFrom + qty;
904	        if (afterFrom > MAX_SAFE)
905	          throw new BizError(
906	            `冲销调拨原单 ${origId}：商品 ${pid} 原调出仓 ${from} 补回后余量超出安全整数范围，拒绝整单`,
907	          );
908	        setStock(this.draft, pid, to, afterTo);
909	        setStock(this.draft, pid, from, afterFrom);
910	        this.additions.push({
911	          seq: ++this.seq, doc: revId, type: revType, product: pid, wh: to,
912	          qty, before: beforeTo, after: afterTo, from, to, orig: origId,
913	        });
914	        this.additions.push({
915	          seq: ++this.seq, doc: revId, type: revType, product: pid, wh: from,
916	          qty, before: beforeFrom, after: afterFrom, from, to, orig: origId,
917	        });
918	        reportLines.push(
919	          `冲销调拨 原单=${origId} 商品=${pid} ${to} -> ${from} ${qty}：` +
920	            `${to} ${beforeTo}->${afterTo}；${from} ${beforeFrom}->${afterFrom}`,
921	        );
922	      }
923	    }
924	
925	    // 全部明细合法：登记冲销关系到模拟视图；库存、流水、关系由 commit 一次性落库
926	    this.revs[revId] = { orig: origId, resultLines: reportLines };
927	    this.newRevIds.push(revId);
928	    this.reversedOrigs.add(origId);
929	
930	    return {
931	      duplicate: false,
932	      header: `冲销单 ${revId} 提交成功，冲销${typeLabel}原单 ${origId}，共 ${pids.length} 种商品：`,
933	      lines: reportLines,
934	    };
935	  }
