937	  /**
938	   * 统一提交：把草稿余量、新增流水、新单据去重记录与冲销关系写回 base 并原子保存。
939	   * 全部项均为重复时不写回、不保存（不改写数据）。
940	   */
941	  commit(dataDir: string): void {
942	    if (!this.changed) return;
943	    this.base.stock = this.draft;
944	    this.base.entries.push(...this.additions);
945	    for (const id of this.newDocIds) this.base.docs[id] = this.docs[id];
946	    for (const id of this.newRevIds) this.base.reversals[id] = this.revs[id];
