1012	const TYPE_LABEL: Record<EntryType, string> = {
1013	  in: '入库',
1014	  out: '出库',
1015	  transfer: '调拨',
1016	  count: '盘点',
1017	  'in-rev': '冲销入库',
1018	  'out-rev': '冲销出库',
