1023	function formatEntry(e: LedgerEntry): string {
1024	  let line: string;
1025	  if (e.type === 'count' || e.type === 'count-rev') {
1026	    const applied = e.type === 'count' ? e.diff! : -e.diff!; // 冲销盘点应用反向差额
1027	    line =
1028	      `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}` +
1029	      `\t差额=${fmtSigned(applied)}\t${e.before}->${e.after}\t账面=${e.expected}\t实盘=${e.actual}`;
1030	  } else {
1031	    let signed: string;
1032	    // 符号必须与前后余量一致：入库/冲销出库/调入方向为增，其余为减
1033	    const increases =
1034	      e.type === 'in' || e.type === 'out-rev' ||
1035	      ((e.type === 'transfer' || e.type === 'transfer-rev') &&
1036	        (e.type === 'transfer') === (e.wh === e.to));
1037	    signed = `${increases ? '+' : '-'}${e.qty}`;
1038	    line = `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}\t${signed}\t${e.before}->${e.after}`;
1039	    if (e.type === 'transfer' || e.type === 'transfer-rev') line += `\t调拨=${e.from}->${e.to}`;
1040	  }
1041	  if (e.orig !== undefined) line += `\t原单=${e.orig}`;
1042	  return line;
1043	}
