1098	/**
1099	 * 整批导入：按列表顺序在同一份草稿上处理各项，后项可见前项生效结果；
1100	 * 任一项失败整批拒绝（此前已保存的单据不撤销，本批任何变动均不落库）。
1101	 * 全部重复时不改写数据。逐项输出编号、首次生效/重复（及重复来源）状态与提交结果。
1102	 */
1103	function runImport(rest: string[], dataDir: string): void {
1104	  const args = parseArgs(rest, ['--file']);
1105	  const file = args.flags['--file'];
1106	  if (file === undefined || args.positionals.length > 0)
1107	    throw new UsageError('用法：import --file <单据列表 JSON 文件>');
1108	
1109	  // 先完整读取并解析文件：文件不可读/解析失败时绝不触碰已提交状态
1110	  const requests = parseImportFile(readImportFile(file));
1111	
1112	  // 参数与文件格式均确认无误后才打开本地数据；损坏数据在此被拒绝且不报告成功
1113	  const store = loadStore(dataDir);
1114	  const ledger = new Ledger(store);
1115	  // 模拟阶段收集输出：只有整批通过并完成保存后才向用户报告，绝不报告部分成功
1116	  const blocks: string[] = [];
1117	  let newCount = 0;
1118	
1119	  requests.forEach((r, i) => {
1120	    const pos = `第 ${i + 1}/${requests.length} 项`;
1121	    // 模拟阶段的业务拒绝同样标注列表位置与原因
1122	    const apply = (): ApplyOutcome => {
1123	      if (r.kind === 'doc') return ledger.applyDoc(r.req);
1124	      if (r.kind === 'count') return ledger.applyCount(r.req);
1125	      return ledger.applyReversal(r.docId, r.orig);
1126	    };
1127	    let outcome: ApplyOutcome;
1128	    try {
1129	      outcome = apply();
1130	    } catch (e) {
1131	      if (e instanceof BizError) throw new BizError(`第 ${i + 1} 项：${e.message}`);
1132	      throw e;
1133	    }
1134	    const id = r.kind === 'reverse' ? r.docId : r.req.docId;
1135	
1136	    let status: string;
1137	    if (outcome.duplicate) {
1138	      const where = outcome.repeatedFrom === 'batch' ? '（本批此前已出现）' : '（导入前已存在）';
1139	      status = `重复${where}，返回原提交结果，不重新核对库存、不追加流水`;
1140	    } else {
1141	      status = '首次生效';
1142	      newCount++;
1143	    }
1144	    blocks.push([`[${pos}] 单据 ${id}：${status}`, outcome.header, ...outcome.lines].join('\n'));
1145	  });
1146	
1147	  // 全部项通过：有新生效单据时整批一次性保存；全部重复则不改写数据
1148	  ledger.commit(dataDir);
1149	
1150	  console.log(`整批导入完成：共 ${requests.length} 项，首次生效 ${newCount} 项，重复 ${requests.length - newCount} 项。`);
1151	  for (const block of blocks) console.log(block);
1152	}
