1189	  拒绝并说明冲突商品及当前量；全部相符才把列出的商品校正为实盘量（差额 =
1190	  实盘 - 账面，可增、可减、可为零；全零差额仍记为成功单据并逐项追加流水），
1191	  未列出的商品及其他仓库不变。同编号同内容重放只返回原结果，即使余量改变或
1192	  盘点已冲销也不再核对、不再生效；同编号不同内容或其他业务拒绝。
1193	
1194	冲销规则：
1195	  冲销在“当前余量”上应用原单的相反变动，不回滚原单之后的其他业务、不恢复绝对
1196	  余量：冲销入库从原目标仓扣回；冲销出库向原来源仓补回；冲销调拨从原调入仓扣
1197	  回并向原调出仓补回；冲销盘点在当前余量上减去原盘点差额（零差额不改余量，
1198	  但仍记录冲销关系与流水）。数量取原单合并后的明细。任一商品扣回不足、补回后
1199	  溢出或冲减后为负则整单拒绝、不占用冲销单编号、原单不标记冲销，条件改善后
1200	  可重试。
1201	  只能冲销成功的原始单据；原单不存在、冲销单本身、已冲销过的原单均不能再次冲
1202	  销，每张原单最多冲销一次。冲销成功后重放原单仍只返回其最初结果，不会重新生
1203	  效；重放冲销单返回原冲销结果，不再变动，同编号改指其他原单则拒绝。
1204	
1205	整批导入规则：
1206	  import --file <文件> 从本地 JSON 文件读取“有序单据对象数组”（至少一项），按
1207	  列表顺序在同一批次中处理：新单据以此前各项生效后的余量核对并计算，后项可以
1208	  使用前项入库所得库存；盘点核对的是此前各项之后的账面量；冲销可指向导入前已
1209	  成功的原单或列表中此前的新原单，尚未出现且未保存的原单不可引用。每张原单最
1210	  多冲销一次，冲销单不可冲销。每项格式（标识去首尾空白后非空、区分大小写）：
1211	    入库 {"type":"in","id":"D1","wh":"W1","items":[{"product":"P1","qty":10}]}
1212	    出库 {"type":"out","id":"D2","wh":"W1","items":[{"product":"P1","qty":4}]}
1213	    调拨 {"type":"transfer","id":"D3","from":"W1","to":"W2","items":[{"product":"P1","qty":2}]}
1214	    盘点 {"type":"count","id":"C1","wh":"W1","items":[{"product":"P1","expected":8,"actual":5}]}
1215	    冲销 {"type":"reverse","id":"R1","orig":"D1"}
1216	  入出库及调拨 qty 为正安全整数，同商品明细先合并再校验；盘点 expected/actual
1217	  均为非负安全整数，同商品重复拒绝。单据编号与单条命令共用唯一空间，不产生批
1218	  次编号：导入前已有或本列表此前出现的“同编号同内容”项只返回原结果，不重新核
1219	  对、不追加流水（即使原单已冲销也不重新生效）；普通单比较类型、仓库及合并后
1220	  商品数量，盘点比较仓库及两种数量，冲销比较原单编号，明细顺序无关。同编号不
1221	  同内容或不同业务整批拒绝。
1222	  整批成功须全部项通过，有新生效单据时整批一次性保存；全部重复时不改写数据。
1223	  任一项格式不合法、缺货、账面冲突、溢出、编号冲突或非法冲销，整批拒绝并指出
1224	  位置和原因：此前已保存的单据不撤销，本批新库存、流水、编号与冲销关系均不保
1225	  留，纠正后可复用这些新编号。文件无法读取、数据损坏或保存失败均不改变已提交
1226	  状态，也不报告部分成功。文件格式或参数错误退出 2，业务拒绝及读写失败退出 1。
1227	
1228	示例：
1229	  node app.ts -d ./data product add P1 螺丝
1230	  node app.ts -d ./data in D1 --wh W1 --item P1:10 --item P2:3
1231	  node app.ts -d ./data out D2 --wh W1 --item P1:4
1232	  node app.ts -d ./data transfer D3 --from W1 --to W2 --item P1:2 --item P1:3
1233	  node app.ts -d ./data count C1 --wh W1 --item P1:1:5 --item P2:3:3
1234	  node app.ts -d ./data reverse R1 --orig D3
1235	  node app.ts -d ./data reverse R2 --orig C1
1236	  node app.ts -d ./data import --file ./docs.json
1237	  node app.ts -d ./data balance P1
1238	  node app.ts -d ./data balance P1 --wh W1
1239	  node app.ts -d ./data flow --product P1
1240	  node app.ts -d ./data flow --wh W2`;
1241	
1242	function printHelp(): void {
1243	  console.log(HELP);
1244	}
1245	
1246	function run(argv: string[]): void {
1247	  // 先抽出全局 -d/--data，其余按命令解析
1248	  let dataDir = DEFAULT_DATA_DIR;
1249	  const rest: string[] = [];
1250	  for (let i = 0; i < argv.length; i++) {
1251	    const t = argv[i];
1252	    if (t === '-d' || t === '--data') {
1253	      if (i + 1 >= argv.length) throw new UsageError(`参数 ${t} 缺少数据目录取值`);
1254	      dataDir = argv[++i];
1255	    } else if (t.startsWith('--data=')) {
1256	      dataDir = t.slice('--data='.length);
1257	    } else {
1258	      rest.push(t);
1259	    }
1260	  }
1261	
1262	  if (rest.length === 0) {
1263	    printHelp();
1264	    return;
1265	  }
1266	  const cmd = rest[0];
1267	  if ((cmd === '-h' || cmd === '--help') && rest.length === 1) {
1268	    printHelp();
1269	    return;
1270	  }
1271	
1272	  const tokens = rest.slice(1);
1273	  switch (cmd) {
1274	    case 'product': {
1275	      const store = loadStore(dataDir);
1276	      runProduct(tokens, dataDir, store);
1277	      break;
1278	    }
1279	    case 'in':
1280	    case 'out':
1281	    case 'transfer': {
1282	      const req = parseDocArgs(cmd, tokens);
1283	      const store = loadStore(dataDir);
1284	      const ledger = new Ledger(store);
1285	      const outcome = ledger.applyDoc(req);
1286	      ledger.commit(dataDir);
1287	      if (outcome.duplicate) {
1288	        console.log(`单据 ${req.docId} 为重复提交，业务内容与原提交一致，返回原提交结果（库存与流水不变）：`);
1289	      } else {
1290	        console.log(outcome.header);
1291	      }
1292	      for (const line of outcome.lines) console.log(line);
1293	      break;
1294	    }
1295	    case 'count': {
1296	      const req = parseCountArgs(tokens);
1297	      const store = loadStore(dataDir);
1298	      const ledger = new Ledger(store);
1299	      const outcome = ledger.applyCount(req);
1300	      ledger.commit(dataDir);
1301	      if (outcome.duplicate) {
1302	        console.log(`盘点单 ${req.docId} 为重复提交，业务内容与原提交一致，返回原提交结果（库存与流水不变）：`);
1303	      } else {
1304	        console.log(outcome.header);
1305	      }
1306	      for (const line of outcome.lines) console.log(line);
1307	      break;
1308	    }
1309	    case 'reverse': {
1310	      const store = loadStore(dataDir);
1311	      runReverse(tokens, dataDir, store);
1312	      break;
1313	    }
1314	    case 'import': {
1315	      runImport(tokens, dataDir);
1316	      break;
1317	    }
1318	    case 'balance': {
1319	      const store = loadStore(dataDir);
1320	      runBalance(tokens, store);
1321	      break;
1322	    }
1323	    case 'flow': {
1324	      const store = loadStore(dataDir);
1325	      runFlow(tokens, store);
1326	      break;
1327	    }
1328	    default:
1329	      throw new UsageError(`未知命令：${cmd}（使用 --help 查看可用命令）`);
1330	  }
1331	}
1332	
1333	try {
1334	  run(process.argv.slice(2));
1335	} catch (e) {
1336	  if (e instanceof UsageError) {
1337	    console.error(`${APP_NAME}: ${e.message}`);
1338	    process.exit(2);
1339	  }
1340	  if (e instanceof BizError || e instanceof DataError) {
1341	    console.error(`${APP_NAME}: ${e.message}`);
1342	    process.exit(1);
1343	  }
1344	  console.error(`${APP_NAME}: 发生未预期错误：${(e as Error)?.stack ?? String(e)}`);
1345	  process.exit(1);
