    if (args.positionals.length > 0) throw new UsageError('用法：po list');
    const ids = Object.keys(store.pos).sort();
    console.log(`已登记采购单（${ids.length}）：`);
    if (ids.length === 0) {
      console.log('（暂无已登记采购单）');
